'use strict';
const CUSTOMER_UI15={difficultyUI12,guestsView,bind,networkPanelHtml14,tnDiagnosisDialog7};
function cafeProfitGuideUI15(id){const g=cafeProfitGuide15(id);show(`<section id="customerGuide15"><span class="eyelabel">CESTA DO ZISKU</span><h2>${esc(loc(id).name)} · rozbor zisku</h2><p>${g.week?'Skutečný uzavřený T'+g.week:'Zatím bez skutečných výsledků'} · ${esc(DIFFICULTIES[state.difficulty].name)}</p>${rows([['Výsledek kavárny',g.profit===null?'—':money(g.profit)],['Obsloužení hosté',g.served??'—'],['Marže na obslouženého hosta',g.contribution===null?'—':money(g.contribution)],['Hosté potřební k pokrytí nákladů',g.breakEven??'Nelze spočítat bez kladné marže'],['Místní pevné náklady',g.fixed===null?'—':money(g.fixed)],['Vedení',g.manager+' · '+money(g.managerCost)+' včetně odvodů']])}<p class="sub">${esc(g.note)} Společné náklady firmy a daň jsou ve financích. Zakladatel nemá smluvní mzdu; najatý manažer musí pokrýt další pravidelný závazek.</p>${g.costs?`<h3>Kam jdou tržby</h3>${rows([['Tržby po DPH',money(g.revenue)],['Lidé včetně vedení, odvodů a přesčasů',money(g.costs.people)],['Nájem a prostory',money(g.costs.premises)],['Spotřebovaná káva',money(g.costs.coffee)],['Suroviny a prodané jídlo',money(g.costs.ingredients)],['Režie, energie, marketing, vybavení a poplatky',money(g.costs.other)],['Chybí do nuly za tento týden',money(g.deficit)]])}`:''}${g.supply?`<h3>Příští dodávka kávy</h3>${rows([['Společná zásoba ve městě',number(g.supply.stock,1)+' kg'],['Včas na cestě',number(g.supply.incoming,1)+' kg'],['Součet cílů zásobovaných kaváren',g.supply.target+' kg'],['Odhad spotřeby této kavárny',number(g.supply.consumption,1)+' kg / týden'],['Další plánovaná objednávka',Math.min(100,g.supply.need)+' kg · '+money(g.supply.orderCost)],['Týdenní limit dodavatele',money(g.supply.budget)]])}${g.supply.orderCost>g.supply.budget?'<p class="bad">Limit nestačí na plánovanou dodávku. Uprav ho v dodávkách kávy, jinak objednávka počká.</p>':''}<p class="sub">Objednávka pod 5 kg se odloží. Platbu může zastavit hotovostní rezerva, celkový rozpočet nebo kapacita dodavatele.</p>`:''}<h3>Co brzdí provoz</h3>${g.reasons.map(r=>`<p>${esc(r.label)} · ${r.count} neobsloužených hostů</p>`).join('')||'<p>Zaznamenaný týden nemá ztracené hosty.</p>'}<div class="actions"><button class="soft" id="customerGuideSupply15">Prověřit dodávky kávy</button><button class="soft" id="customerGuideTeam15">Upravit tým a směny</button><button class="soft" id="customerGuideMenu15">Prověřit menu a ceny</button></div><h3>Prověřitelné možnosti</h3><p>Žádný zásah se neprovede sám. Odhad omezuje dostupná káva, směny a nynější ceny; nezahrnuje teprve příchozí zásilky.</p>${g.variants.map((q,i)=>`<article class="card"><h3>${esc(q.action.label)}</h3>${rows([['Platba nyní',money(q.cost)],['Odhad výsledku před / po',money(q.before.profit)+' / '+money(q.after.profit)],['Další náklady týdně',money(q.weekly)+' / týden']])}<button class="soft" data-customer-profit15="${i}">Prověřit konkrétní zásah</button></article>`).join('')||'<p>V rámci nynějšího rozpočtu není dostupný zlepšující zásah. Prověř cenu a dostupnost kávy, rozpis i nájem.</p>'}<div class="actions"><button class="soft" id="customerGuideBack15">Zpět na můj panel</button><button class="soft" id="customerGuideFinance15">Finance firmy</button></div></section>`);on('[data-customer-profit15]',b=>tnQuoteDialog7(id,tnQuote7(id,g.variants[Number(b.dataset.customerProfit15)].action)));el('customerGuideSupply15').onclick=()=>gameSupplierDialog6(id);el('customerGuideTeam15').onclick=()=>{crewSelected5=id;crewTab6='teams';el('modal').close();goto('crew');};el('customerGuideMenu15').onclick=()=>{menuStore=id;el('modal').close();goto('menu');};el('customerGuideBack15').onclick=()=>networkOpen14();el('customerGuideFinance15').onclick=()=>{el('modal').close();goto('finance');};}
networkPanelHtml14=function(){return CUSTOMER_UI15.networkPanelHtml14()+`<section class="card"><h3>Cesta kavárny do zisku</h3><p>Skutečná marže, potřebný počet hostů a placené možnosti zlepšení.</p>${state.stores.filter(s=>!s.franchise).map(s=>`<button class="soft" data-customer-guide15="${s.id}">${esc(loc(s.id).name)} · rozebrat zisk</button>`).join('')||'<p>První rozbor získáš po otevření kavárny.</p>'}</section>`;};
const CUSTOMER_BIND14=networkBind14;networkBind14=function(){CUSTOMER_BIND14();on('[data-customer-guide15]',b=>cafeProfitGuideUI15(b.dataset.customerGuide15));};
tnDiagnosisDialog7=function(id){CUSTOMER_UI15.tnDiagnosisDialog7(id);const b=document.createElement('button');b.className='primary';b.id='customerProfitGuide15';b.textContent='Cesta kavárny do zisku';b.onclick=()=>cafeProfitGuideUI15(id);el('modalContent').querySelector('h2').after(b);};
difficultyUI12=function(){CUSTOMER_UI15.difficultyUI12();const intro=document.createElement('p');intro.className='sub';intro.textContent='Pohodová dává větší prostor pro učení: návštěvnost 160 %, výkon obsluhy 220 %. Standard: 118 % / 150 %. Expert: 92 % / 100 %. Dodávky počítají spotřebu do doručení i více kaváren ve městě. Zaplacené nájmy, mzdy a minulé výsledky zůstávají.';el('modalContent').querySelector('h2').after(intro);};
let customerTab15='market',customerSelected15=null;const customerDrafts15=new Map();
function customerReadForm15(){if(!el('customerEnabled15')||!el('customerBudget15'))return null;const data={enabled:el('customerEnabled15').checked,budget:Number(el('customerBudget15').value),reserve:Number(el('customerReserve15').value)};if(customerTab15==='loyalty')data.reward=Number(el('customerReward15').value);else if(customerTab15==='offers')Object.assign(data,{group:el('customerGroup15').value,period:el('customerPeriod15').value,discount:Number(el('customerDiscount15').value),weeks:Number(el('customerWeeks15').value),kind:el('customerKind15').value});else return null;return data;}
function customerRememberDraft15(){const data=customerReadForm15();if(data)customerDrafts15.set(customerTab15+':'+customerSelected15,data);}

function customerNodeLabel15(n){return (n.side==='player'?'Tvoje firma':state.rivals.find(r=>r.id===n.rival)?.name||'Soupeř')+' · '+loc(n.location).name;}
function customerSalesHtml15(id){const h=state.customers15.history.slice().reverse().find(h=>h.sales.some(s=>s.id===id)),r=h?.sales.find(s=>s.id===id);return r?`<h3>Skutečně uzavřený T${h.week}</h3>${rows([['Obsloužení hosté',r.served],['Uplatněné věrnostní odměny',r.groups.reduce((n,g)=>n+g.redeemed,0)+' · '+money(r.loyaltyDiscount)],['Cíleně zlevněné nápoje',r.groups.reduce((n,g)=>n+g.discounted,0)+' · '+money(r.offerDiscount)],['Celkové snížení tržby',money(r.discount)]])}<p class="sub">Sleva už je v tržbě a výsledku kavárny. Káva, suroviny, obsluha a DPH jsou ve stejném prodeji. Žádný další prodej ani druhá platba slevy.</p>`:'<p class="sub">Výsledek programu se objeví po skutečně odehraném týdnu.</p>';}
function customerMarketHtml15(id){const history=state.customers15.history.slice(-4),moves=history.flatMap(h=>h.flows.filter(f=>f.from.side==='player'&&f.from.location===id||f.to.side==='player'&&f.to.location===id).map(f=>({...f,week:h.week}))),incoming=moves.filter(f=>f.to.side==='player'&&f.to.location===id).reduce((n,f)=>n+f.count,0),outgoing=moves.filter(f=>f.from.side==='player'&&f.from.location===id).reduce((n,f)=>n+f.count,0),outside=history.flatMap(h=>h.outside).filter(f=>f.from.side==='player'&&f.from.location===id).reduce((n,f)=>n+f.count,0);return `<h3>Kdo získává stálé hosty</h3><p>Poslední čtyři uzavřené týdny. Přesun změní zákaznický okruh až pro další týden; nynější návštěvy a tržby nepřepisuje.</p><div class="customer-metrics15">${metric('PŘIŠLI Z JINÉHO PROVOZU',incoming,'Modelované přesuny do této kavárny')}${metric('PŘEŠLI DO JINÉHO PROVOZU',outgoing,'Konkrétní blízká kavárna')}${metric('ODEŠLI MIMO SLEDOVANOU SÍŤ',outside,'Zbytek skutečných odchodů')}</div>${moves.slice().reverse().map(f=>`<article class="news"><div><strong>T${f.week} · ${f.count} · ${esc(GUEST_TYPES5[f.group].name)}</strong><p>${esc(customerNodeLabel15(f.from))} → ${esc(customerNodeLabel15(f.to))}</p><small>${esc(f.reason)}</small></div></article>`).join('')||empty('Zatím žádný modelovaný přesun. Okruhy soupeřů vznikají z jejich skutečně obsloužených hostů; před prvním týdnem nejsou vymyšlené.') }<p class="sub">Jde o model části odcházejících skupin, nikoli sledování konkrétních lidí. Rozhodují cena, kvalita, obsluha a vzdálenost do 35 mapových jednotek. Přesun je omezen skutečným odchodem a kapacitou cílového okruhu. Vlastní pobočky si mohou hosty převzít také mezi sebou.</p>`;}
function customerLoyaltyHtml15(id){const p=customerPolicy15('loyalty',id),d=customerDrafts15.get('loyalty:'+id)||p?.data||{enabled:true,reward:20,budget:2000,reserve:2},points=p?.points.reduce((n,x)=>n+x.value,0)||0;return `<h3>Vlastní papírový věrnostní program</h3><p>Šest zaplacených návratů stálých hostů vytvoří nárok na slevu při dalším skutečném návratu. Odměna je nejvýše čtvrtina průměrné ceny kávy. Body se vedou souhrnně po skupinách hostů a při pozastavení se zachovají.</p>${rows([['Příprava programu',p?'Už zaplaceno '+money(p.fee):money(1500)+' jednorázově'],['Nasbírané body',points],['Stav',p?.data.enabled?'Aktivní':p?'Pozastavený':'Zatím nezaložený']])}<div class="fields">${field('Povolit program',`<input id="customerEnabled15" type="checkbox" ${d.enabled?'checked':''}>`)}${field('Odměna / Kč',input('customerReward15',d.reward,10,25,1))}${field('Týdenní limit všech odměn / Kč',input('customerBudget15',d.budget,0,20000,100))}${field('Chráněná rezerva / týdny',input('customerReserve15',d.reserve,1,8,1))}</div><div class="actions"><button class="primary" id="customerQuote15">Prověřit program</button>${p?.data.enabled?'<button class="soft" id="customerPause15">Pozastavit bez platby</button>':''}</div>${customerReturnReportHtml15(id,p?.started)}${customerSalesHtml15(id)}`;}
function customerOfferHtml15(id){const p=customerPolicy15('offers',id),d=customerDrafts15.get('offers:'+id)||p?.data||{enabled:true,group:'office',period:'morning',discount:10,weeks:4,budget:2000,reserve:2,kind:'offer'};return `<h3>Cílená nabídka hostům</h3><p>Zvol skupinu a denní období. Příprava kampaně stojí 2 500 Kč; slevy mají samostatný týdenní strop. Nabídka lehce mění skladbu stávající poptávky. Dostupná káva a obsluha stále omezují prodej.</p>${p?`<p>Současná nabídka: ${p.data.enabled&&p.end>=state.week?'aktivní':'pozastavená nebo skončená'} · do T${p.end} · zaplacené přípravy ${money(p.fee)}. Obnovení období je nová placená kampaň.</p>`:''}<div class="fields">${field('Povolit nabídku',`<input id="customerEnabled15" type="checkbox" ${d.enabled?'checked':''}>`)}${field('Skupina hostů',`<select id="customerGroup15">${Object.entries(GUEST_TYPES5).map(([k,v])=>option(k,v.name,d.group)).join('')}</select>`)}${field('Kdy platí sleva',`<select id="customerPeriod15">${Object.entries(CUSTOMER_PERIODS15).map(([k,v])=>option(k,v,d.period)).join('')}</select>`)}${field('Typ nabídky',`<select id="customerKind15">${option('offer','Nabídka běžné kávy',d.kind)}${option('tasting','Degustační nabídka vlastní kávy',d.kind)}</select>`)}${field('Sleva na skutečný nápoj / Kč',input('customerDiscount15',d.discount,5,25,1))}${field('Nové období / týdny',`<select id="customerWeeks15">${[2,4,8].map(n=>option(n,n,d.weeks)).join('')}</select>`)}${field('Týdenní limit slev / Kč',input('customerBudget15',d.budget,0,20000,100))}${field('Chráněná rezerva / týdny',input('customerReserve15',d.reserve,1,8,1))}</div><p class="sub">Degustace zlevňuje existující nápoj z fyzicky spotřebované vlastní autentické šarže. Bez ní se sleva neuplatní. Nabídky se s věrnostní odměnou na stejném nápoji nesčítají.</p><div class="actions"><button class="primary" id="customerQuote15">Prověřit cílenou nabídku</button>${p?.data.enabled?'<button class="soft" id="customerPause15">Pozastavit bez platby</button>':''}</div>${customerSalesHtml15(id)}`;}
function customerOpenUI15(tab='market',remember=true){if(remember)customerRememberDraft15();customerTab15=tab;const own=state.stores.filter(s=>!s.franchise);if(!own.some(s=>s.id===customerSelected15))customerSelected15=own[0]?.id||null;show(`<span class="eyelabel">HOSTÉ A NÁVRATY</span><h2>Zákazníci a nabídky</h2><div class="network-tabs14" role="tablist" aria-label="Zákaznické programy">${[['market','Přesuny hostů'],['loyalty','Věrnostní program'],['offers','Cílené nabídky']].map(([key,label])=>`<button class="soft" id="customerTab-${key}" role="tab" aria-controls="customerBody15" aria-selected="${tab===key}" tabindex="${tab===key?0:-1}" data-customer-tab15="${key}">${label}</button>`).join('')}</div>${customerSelected15?`${field('Kavárna',`<select id="customerStore15">${own.map(s=>option(s.id,loc(s.id).city+' · '+loc(s.id).name,customerSelected15)).join('')}</select>`)}<button class="soft" id="customerProfit15">Cesta této kavárny do zisku</button><section id="customerBody15" role="tabpanel" aria-labelledby="customerTab-${tab}">${tab==='market'?customerMarketHtml15(customerSelected15):tab==='loyalty'?customerLoyaltyHtml15(customerSelected15):customerOfferHtml15(customerSelected15)}</section>`:'<p>Nejdřív otevři vlastní kavárnu. Nové programy nezačnou samy a nic předem neplatíš.</p>'}`);const tabs=[...el('modalContent').querySelectorAll('[data-customer-tab15]')];tabs.forEach((b,i)=>{b.onclick=()=>{customerOpenUI15(b.dataset.customerTab15);el('customerTab-'+b.dataset.customerTab15).focus();};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:-1)+3)%3;customerOpenUI15(tabs[index].dataset.customerTab15);el('customerTab-'+tabs[index].dataset.customerTab15).focus();};});if(el('customerStore15'))el('customerStore15').onchange=()=>{customerRememberDraft15();customerSelected15=el('customerStore15').value;customerOpenUI15(customerTab15,false);};if(el('customerProfit15'))el('customerProfit15').onclick=()=>cafeProfitGuideUI15(customerSelected15);if(el('customerQuote15'))el('customerQuote15').onclick=customerQuoteUI15;if(el('customerPause15'))el('customerPause15').onclick=()=>{if(act(()=>pauseCustomerPolicy15(customerTab15,customerSelected15),'Program pozastaven.')){customerDrafts15.delete(customerTab15+':'+customerSelected15);customerOpenUI15(customerTab15,false);}};}
function customerQuoteUI15(){const kind=customerTab15,id=customerSelected15,data=customerReadForm15();customerRememberDraft15();try{const q=customerPolicyQuote15(kind,id,data);show(`<span class="eyelabel">NÁHLED · NIC ZATÍM NEBYLO ZAPLACENO</span><h2>${kind==='loyalty'?'Věrnostní program':'Cílená nabídka'} · ${esc(loc(id).name)}</h2>${rows([['Příprava nyní',money(q.fee)],['Týdenní strop slev',money(data.budget)],['Rezerva včetně plného stropu',money(q.protectedCash)],['Hotovost po přípravě',money(state.cash-q.fee)],['Odměna / sleva',money(data.reward||data.discount)],...(kind==='offers'?[['Hosté',GUEST_TYPES5[data.group].name],['Období',CUSTOMER_PERIODS15[data.period]],['Konec nové kampaně','T'+q.end]]:[])])}<p>Odměny a slevy se odečtou jen od skutečně prodaných nápojů, nejvýše 25 % průměrné ceny kávy. Nezvyšují počet obsloužených návštěv. Příprava se účtuje ve čtvrtletním rozpočtu značek.</p>${data.kind==='tasting'?'<p class="warning">Degustační nabídka vyžaduje fyzicky spotřebovanou vlastní autentickou šarži. Zaplacená příprava sama kávu nevytvoří.</p>':''}${!q.safe?'<p class="warning">Na přípravu, plný strop slev a provozní rezervu chybí hotovost.</p>':''}<div class="actions"><button class="primary" id="customerConfirm15" ${!q.safe?'disabled':''}>Potvrdit placenou přípravu</button><button class="soft" id="customerCancel15">Zpět bez platby</button></div>`);el('customerCancel15').onclick=()=>customerOpenUI15(kind);el('customerConfirm15').onclick=()=>{if(act(()=>setCustomerPolicy15(kind,id,data,q),'Program připraven.')){customerDrafts15.delete(kind+':'+id);customerOpenUI15(kind,false);}};}catch(e){toast(e.message);}}
guestsView=function(){return `<section class="card"><h2>Zákazníci, konkurence a nabídky</h2><p>Skutečné návraty, modelované přesuny a cílené slevy s vlastním rozpočtem.</p><button class="primary" id="customerOpen15">Otevřít zákazníky a nabídky</button></section>`+CUSTOMER_UI15.guestsView();};
bind=function(){CUSTOMER_UI15.bind();if(el('customerOpen15'))el('customerOpen15').onclick=()=>customerOpenUI15();};
const CUSTOMER_PANEL15=networkPanelHtml14;networkPanelHtml14=function(){return `<div class="actions"><button class="soft" id="networkCustomers15">Zákazníci a nabídky</button></div>`+CUSTOMER_PANEL15();};
const CUSTOMER_PANEL_BIND15=networkBind14;networkBind14=function(){CUSTOMER_PANEL_BIND15();if(el('networkCustomers15'))el('networkCustomers15').onclick=()=>customerOpenUI15();};
render();

function customerReturnReportHtml15(id,started){const s=tnStore7(id),current=s.guests5.history.slice(-4),previous=s.guests5.history.filter(h=>h.week<started).slice(-4),summarize=a=>({weeks:a.length,served:a.reduce((n,h)=>n+h.served,0),returned:a.reduce((n,h)=>n+h.returned,0)}),now=summarize(current),before=summarize(previous);return `<h3>Návraty stálých hostů</h3>${rows([['Poslední skutečné týdny',now.weeks?'Týdnů: '+now.weeks+' · '+now.returned+' návratů z '+now.served+' obsloužených ('+number(now.returned/Math.max(1,now.served)*100,1)+' %)':'Zatím bez historie'],['Před zahájením programu',before.weeks?'Týdnů: '+before.weeks+' · '+before.returned+' návratů z '+before.served+' obsloužených ('+number(before.returned/Math.max(1,before.served)*100,1)+' %)':'Zatím bez srovnání']])}<p class="sub">Skutečně zaznamenané návštěvy; změna zahrnuje také obsluhu, počasí, ceny a konkurenci. Není sama důkazem účinku odměn.</p>`;}
